import{BaseError,encodeFunctionData}from"viem";import{getContractError,parseAccount}from"viem/utils";import{}from"viem/zksync";import{AccountNotFoundError}from"../errors/account.js";import{sendTransaction}from"./sendTransaction.js";export async function writeContract(client,signerClient,publicClient,parameters,isPrivyCrossApp=!1){const{abi:abi,account:account_=client.account,address:address,args:args,dataSuffix:dataSuffix,functionName:functionName,...request}=parameters;if(!account_)throw new AccountNotFoundError({docsPath:"/docs/contract/writeContract"});const account=parseAccount(account_),data=encodeFunctionData({abi:abi,args:args,functionName:functionName});try{return await sendTransaction(client,signerClient,publicClient,{data:`${data}${dataSuffix?dataSuffix.replace("0x",""):""}`,to:address,account:account,...request},isPrivyCrossApp)}catch(error){throw getContractError(error,{abi:abi,address:address,args:args,docsPath:"/docs/contract/writeContract",functionName:functionName,sender:account.address})}}