import{createClient,createPublicClient,createWalletClient,custom,http}from"viem";import{toAccount}from"viem/accounts";import{sessionWalletActions}from"./walletActions.js";export function toSessionClient({client:client,signer:signer,session:session,paymasterHandler:paymasterHandler}){return createSessionClient({account:client.account,chain:client.chain,session:session,signer:signer,transport:custom(client.transport),paymasterHandler:paymasterHandler})}export function createSessionClient({account:account,signer:signer,chain:chain,transport:transport,session:session,paymasterHandler:paymasterHandler,nonceManager:nonceManager}){transport||(transport=http(void 0,{batch:!0}));const publicClient=createPublicClient({transport:transport,chain:chain}),parsedAccount="string"==typeof account?toAccount(account):account;nonceManager&&(parsedAccount.nonceManager=nonceManager);const baseClient=createClient({account:parsedAccount,chain:chain,transport:transport}),signerWalletClient=createWalletClient({account:signer,chain:chain,transport:transport});return baseClient.extend(sessionWalletActions(signerWalletClient,publicClient,session,paymasterHandler))}