import{createClient,createPublicClient,createWalletClient,http}from"viem";import{toAccount}from"viem/accounts";import{}from"viem/zksync";import{getSmartAccountAddressFromInitialSigner}from"./utils.js";import{globalWalletActions}from"./walletActions.js";export async function createAbstractClient({signer:signer,chain:chain,transport:transport,address:address,isPrivyCrossApp:isPrivyCrossApp=!1,publicTransport:publicTransport=http(void 0,{batch:!0}),customPaymasterHandler:customPaymasterHandler}){if(!transport)throw new Error("Transport is required");const publicClient=createPublicClient({chain:chain,transport:publicTransport}),smartAccountAddress=address??await getSmartAccountAddressFromInitialSigner(signer.address,publicClient),baseClient=createClient({account:toAccount(smartAccountAddress),chain:chain,transport:transport}),signerWalletClient=createWalletClient({account:signer,chain:chain,transport:transport});return baseClient.extend(globalWalletActions(signerWalletClient,publicClient,isPrivyCrossApp,customPaymasterHandler))}